rules.query:
DeviceEvents
| where ActionType == "OpenProcessApiCall"
// For OpenProcessApiCall, FileName is the TARGET process and
// InitiatingProcessFileName is the accessor. AdditionalFields holds only
// {DesiredAccess}, NOT TargetProcessName (confirmed via purple-team validation
// 2026-07-04), so the old Fields.TargetProcessName filter silently never fired.
| where FileName =~ "lsass.exe"
| where InitiatingProcessFileName !in~ ("MsMpEng.exe", "csrss.exe", "wininit.exe", "services.exe", "lsaiso.exe", "SecurityHealthSystray.exe", "WerFault.exe", "taskmgr.exe", "SenseIR.exe")
| extend DesiredAccess = tostring(parse_json(AdditionalFields).DesiredAccess)
| project Timestamp, DeviceName, TargetProcess = FileName, InitiatingProcessFileName, InitiatingProcessCommandLine, DesiredAccess

DeviceEvents
| where ActionType == "CreateRemoteThreadApiCall"
// For CreateRemoteThreadApiCall, FileName is the TARGET process (where the thread
// was created) and InitiatingProcessFileName is the injector. AdditionalFields
// .TargetProcessName is empty for this ActionType (confirmed via purple-team
// validation 2026-07-04), so filtering on it silently never fired.
| where FileName in~ ("lsass.exe", "winlogon.exe", "explorer.exe", "services.exe", "svchost.exe")
| where InitiatingProcessFileName !in~ ("MsMpEng.exe", "WerFault.exe", "SenseIR.exe", "svchost.exe")
| project Timestamp, DeviceName, TargetProcess = FileName, InitiatingProcessFileName, InitiatingProcessCommandLine
